class ProductData extends DataClass implements Insertable<ProductData> {
  final String? id;
  final String? categoryId;
  final String name;
  final String? nameAlt;
  final String? sku;
  final String? barcode;
  final String? imagePath;
  final int basePriceMinor;
  final String? taxRateId;
  final String unit;

  /// pc | kg | g | l | ml
  final int available;
  final int trackStock;
  final String kind;
  final String? station;

  /// counter/station override (tandoor, tea, bbq...); null = the category's station
  final int version;
  final int updatedAt;
  final int? deletedAt;
  final String? description;

  /// a line about the dish, printed on the shared menu picture
  final int askPrice;
  const ProductData({
    this.id,
    this.categoryId,
    required this.name,
    this.nameAlt,
    this.sku,
    this.barcode,
    this.imagePath,
    required this.basePriceMinor,
    this.taxRateId,
    required this.unit,
    required this.available,
    required this.trackStock,
    required this.kind,
    this.station,
    required this.version,
    required this.updatedAt,
    this.deletedAt,
    this.description,
    required this.askPrice,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (!nullToAbsent || id != null) {
      map['id'] = Variable<String>(id);
    }
    if (!nullToAbsent || categoryId != null) {
      map['category_id'] = Variable<String>(categoryId);
    }
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || nameAlt != null) {
      map['name_alt'] = Variable<String>(nameAlt);
    }
    if (!nullToAbsent || sku != null) {
      map['sku'] = Variable<String>(sku);
    }
    if (!nullToAbsent || barcode != null) {
      map['barcode'] = Variable<String>(barcode);
    }
    if (!nullToAbsent || imagePath != null) {
      map['image_path'] = Variable<String>(imagePath);
    }
    map['base_price_minor'] = Variable<int>(basePriceMinor);
    if (!nullToAbsent || taxRateId != null) {
      map['tax_rate_id'] = Variable<String>(taxRateId);
    }
    map['unit'] = Variable<String>(unit);
    map['available'] = Variable<int>(available);
    map['track_stock'] = Variable<int>(trackStock);
    map['kind'] = Variable<String>(kind);
    if (!nullToAbsent || station != null) {
      map['station'] = Variable<String>(station);
    }
    map['version'] = Variable<int>(version);
    map['updated_at'] = Variable<int>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<int>(deletedAt);
    }
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    map['ask_price'] = Variable<int>(askPrice);
    return map;
  }

  ProductCompanion toCompanion(bool nullToAbsent) {
    return ProductCompanion(
      id: id == null && nullToAbsent ? const Value.absent() : Value(id),
      categoryId: categoryId == null && nullToAbsent
          ? const Value.absent()
          : Value(categoryId),
      name: Value(name),
      nameAlt: nameAlt == null && nullToAbsent
          ? const Value.absent()
