class OrderData extends DataClass implements Insertable<OrderData> {
  final String? id;
  final String? invoiceNo;

  /// assigned at settlement, null while a draft/held
  final String orderType;
  final String status;
  final String? tableId;
  final String? customerId;
  final String? waiterId;
  final String? cashierId;
  final String? shiftId;
  final String? riderId;
  final int? guests;
  final String? note;
  final String? deliveryAddress;
  final String source;

  /// pos | online
  final String? billConfig;

  /// JSON of discount/service/delivery/tip/rounding so the bill can be recomputed exactly
  final int subtotalMinor;
  final int discountMinor;
  final int serviceChargeMinor;
  final int deliveryChargeMinor;
  final int taxMinor;
  final int tipMinor;
  final int roundingMinor;
  final int totalMinor;
  final int paidMinor;
  final String businessDate;
  final int createdAt;
  final int updatedAt;
  final int? settledAt;
  final int version;
  final String? waiterMemberId;
  const OrderData({
    this.id,
    this.invoiceNo,
    required this.orderType,
    required this.status,
    this.tableId,
    this.customerId,
    this.waiterId,
    this.cashierId,
    this.shiftId,
    this.riderId,
    this.guests,
    this.note,
    this.deliveryAddress,
    required this.source,
    this.billConfig,
    required this.subtotalMinor,
    required this.discountMinor,
    required this.serviceChargeMinor,
    required this.deliveryChargeMinor,
    required this.taxMinor,
    required this.tipMinor,
    required this.roundingMinor,
    required this.totalMinor,
    required this.paidMinor,
    required this.businessDate,
    required this.createdAt,
    required this.updatedAt,
    this.settledAt,
    required this.version,
    this.waiterMemberId,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    if (!nullToAbsent || id != null) {
      map['id'] = Variable<String>(id);
    }
    if (!nullToAbsent || invoiceNo != null) {
      map['invoice_no'] = Variable<String>(invoiceNo);
