    }
    if (!nullToAbsent || waiterId != null) {
      map['waiter_id'] = Variable<String>(waiterId);
    }
    if (!nullToAbsent || cashierId != null) {
      map['cashier_id'] = Variable<String>(cashierId);
    }
    if (!nullToAbsent || shiftId != null) {
      map['shift_id'] = Variable<String>(shiftId);
    }
    if (!nullToAbsent || riderId != null) {
      map['rider_id'] = Variable<String>(riderId);
    }
    if (!nullToAbsent || guests != null) {
      map['guests'] = Variable<int>(guests);
    }
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    if (!nullToAbsent || deliveryAddress != null) {
      map['delivery_address'] = Variable<String>(deliveryAddress);
    }
    map['source'] = Variable<String>(source);
    if (!nullToAbsent || billConfig != null) {
      map['bill_config'] = Variable<String>(billConfig);
