    map['subtotal_minor'] = Variable<int>(subtotalMinor);
    map['discount_minor'] = Variable<int>(discountMinor);
    map['service_charge_minor'] = Variable<int>(serviceChargeMinor);
    map['delivery_charge_minor'] = Variable<int>(deliveryChargeMinor);
    map['tax_minor'] = Variable<int>(taxMinor);
    map['tip_minor'] = Variable<int>(tipMinor);
    map['rounding_minor'] = Variable<int>(roundingMinor);
    map['total_minor'] = Variable<int>(totalMinor);
    map['paid_minor'] = Variable<int>(paidMinor);
    map['business_date'] = Variable<String>(businessDate);
    map['created_at'] = Variable<int>(createdAt);
    map['updated_at'] = Variable<int>(updatedAt);
    if (!nullToAbsent || settledAt != null) {
