class OrderItemData extends DataClass implements Insertable<OrderItemData> {
  final String? id;
  final String orderId;
  final String productId;
  final String? variantId;
  final String name;

  /// snapshot: receipts must not change when the menu changes
  final int qtyMilli;
  final int unitPriceMinor;
  final int discountMinor;
  final int taxRateBp;
  final int taxInclusive;
  final int taxMinor;
  final int lineTotalMinor;
  final String? note;
  final String? station;
  final int? kotSentAt;
  final int kotQtyMilli;

  /// quantity the kitchen has already been sent; the next KOT prints only the difference
  final String status;
  const OrderItemData({
    this.id,
    required this.orderId,
    required this.productId,
    this.variantId,
    required this.name,
    required this.qtyMilli,
    required this.unitPriceMinor,
    required this.discountMinor,
    required this.taxRateBp,
    required this.taxInclusive,
    required this.taxMinor,
