    map['order_id'] = Variable<String>(orderId);
    map['product_id'] = Variable<String>(productId);
    if (!nullToAbsent || variantId != null) {
      map['variant_id'] = Variable<String>(variantId);
    }
    map['name'] = Variable<String>(name);
    map['qty_milli'] = Variable<int>(qtyMilli);
    map['unit_price_minor'] = Variable<int>(unitPriceMinor);
    map['discount_minor'] = Variable<int>(discountMinor);
    map['tax_rate_bp'] = Variable<int>(taxRateBp);
    map['tax_inclusive'] = Variable<int>(taxInclusive);
    map['tax_minor'] = Variable<int>(taxMinor);
    map['line_total_minor'] = Variable<int>(lineTotalMinor);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    if (!nullToAbsent || station != null) {
      map['station'] = Variable<String>(station);
    }
    if (!nullToAbsent || kotSentAt != null) {
      map['kot_sent_at'] = Variable<int>(kotSentAt);
    }
    map['kot_qty_milli'] = Variable<int>(kotQtyMilli);
    map['status'] = Variable<String>(status);
    return map;
  }

