class OutboxData extends DataClass implements Insertable<OutboxData> {
  /// one row per change; drained oldest-first, retried with backoff
  final int seq;
  final String idempotencyKey;

  /// server ignores a key it has already applied: no duplicate sales
  final String entity;
  final String entityId;
  final String op;
  final String payload;
  final int? entityVersion;
  final int createdAt;
  final int attempts;
  final int nextAttemptAt;
  final String? lastError;
  final int? ackedAt;
