final class $AttendanceReferences
    extends BaseReferences<_$AppDatabase, Attendance, AttendanceData> {
  $AttendanceReferences(super.$_db, super.$_table, super.$_typedResult);

  static Staff _staffIdTable(_$AppDatabase db) => db.staff.createAlias(
    $_aliasNameGenerator(db.attendance.staffId, db.staff.id),
  );

  $StaffProcessedTableManager get staffId {
    final $_column = $_itemColumn<String>('staff_id')!;

    final manager = $StaffTableManager(
      $_db,
      $_db.staff,
    ).filter((f) => f.id.sqlEquals($_column));
    final item = $_typedResult.readTableOrNull(_staffIdTable($_db));
    if (item == null) return manager;
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: [item]),
    );
  }
}

