          createFilteringComposer: () =>
              $ShiftFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $ShiftOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $ShiftAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String?> id = const Value.absent(),
                Value<String> staffId = const Value.absent(),
                Value<int> openedAt = const Value.absent(),
                Value<int> openingCashMinor = const Value.absent(),
                Value<int?> closedAt = const Value.absent(),
                Value<int?> closingCashCountedMinor = const Value.absent(),
                Value<int?> expectedCashMinor = const Value.absent(),
                Value<int?> varianceMinor = const Value.absent(),
                Value<String?> note = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => ShiftCompanion(
                id: id,
                staffId: staffId,
                openedAt: openedAt,
                openingCashMinor: openingCashMinor,
                closedAt: closedAt,
                closingCashCountedMinor: closingCashCountedMinor,
                expectedCashMinor: expectedCashMinor,
                varianceMinor: varianceMinor,
                note: note,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                Value<String?> id = const Value.absent(),
                required String staffId,
                required int openedAt,
                Value<int> openingCashMinor = const Value.absent(),
                Value<int?> closedAt = const Value.absent(),
                Value<int?> closingCashCountedMinor = const Value.absent(),
                Value<int?> expectedCashMinor = const Value.absent(),
                Value<int?> varianceMinor = const Value.absent(),
                Value<String?> note = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => ShiftCompanion.insert(
                id: id,
                staffId: staffId,
                openedAt: openedAt,
                openingCashMinor: openingCashMinor,
                closedAt: closedAt,
                closingCashCountedMinor: closingCashCountedMinor,
                expectedCashMinor: expectedCashMinor,
                varianceMinor: varianceMinor,
                note: note,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map((e) => (e.readTable(table), $ShiftReferences(db, table, e)))
              .toList(),
          prefetchHooksCallback:
              ({
                staffId = false,
                orderRefs = false,
                paymentRefs = false,
                refundRefs = false,
                cashMovementRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (orderRefs) db.order,
                    if (paymentRefs) db.payment,
                    if (refundRefs) db.refund,
                    if (cashMovementRefs) db.cashMovement,
                  ],
                  addJoins:
                      <
                        T extends TableManagerState<
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic
