                                    currentTable: table,
                                    currentColumn: table.staffId,
                                    referencedTable: $ShiftReferences
                                        ._staffIdTable(db),
                                    referencedColumn: $ShiftReferences
                                        ._staffIdTable(db)
                                        .id,
