                          currentTable: table,
                          referencedTable: $ShiftReferences._orderRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $ShiftReferences(db, table, p0).orderRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.shiftId == item.id,
                              ),
                          typedResults: items,
                        ),
                      if (paymentRefs)
                        await $_getPrefetchedData<
                          ShiftData,
                          Shift,
                          PaymentData
                        >(
                          currentTable: table,
                          referencedTable: $ShiftReferences._paymentRefsTable(
                            db,
                          ),
                          managerFromTypedResult: (p0) =>
                              $ShiftReferences(db, table, p0).paymentRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.shiftId == item.id,
                              ),
                          typedResults: items,
                        ),
                      if (refundRefs)
                        await $_getPrefetchedData<ShiftData, Shift, RefundData>(
                          currentTable: table,
                          referencedTable: $ShiftReferences._refundRefsTable(
                            db,
                          ),
                          managerFromTypedResult: (p0) =>
                              $ShiftReferences(db, table, p0).refundRefs,
                          referencedItemsForCurrentItem:
