          createOrderingComposer: () =>
              $RecipeLineOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $RecipeLineAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> productId = const Value.absent(),
                Value<String?> variantId = const Value.absent(),
                Value<String> stockItemId = const Value.absent(),
                Value<int> qtyMilli = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => RecipeLineCompanion(
                productId: productId,
                variantId: variantId,
                stockItemId: stockItemId,
                qtyMilli: qtyMilli,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String productId,
                Value<String?> variantId = const Value.absent(),
                required String stockItemId,
                required int qtyMilli,
                Value<int> rowid = const Value.absent(),
              }) => RecipeLineCompanion.insert(
                productId: productId,
                variantId: variantId,
                stockItemId: stockItemId,
                qtyMilli: qtyMilli,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) =>
                    (e.readTable(table), $RecipeLineReferences(db, table, e)),
              )
              .toList(),
          prefetchHooksCallback:
              ({productId = false, variantId = false, stockItemId = false}) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [],
                  addJoins:
                      <
                        T extends TableManagerState<
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic
                        >
                      >(state) {
                        if (productId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.productId,
                                    referencedTable: $RecipeLineReferences
                                        ._productIdTable(db),
                                    referencedColumn: $RecipeLineReferences
                                        ._productIdTable(db)
                                        .id,
                                  )
                                  as T;
                        }
                        if (variantId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.variantId,
                                    referencedTable: $RecipeLineReferences
                                        ._variantIdTable(db),
                                    referencedColumn: $RecipeLineReferences
                                        ._variantIdTable(db)
                                        .id,
                                  )
                                  as T;
                        }
                        if (stockItemId) {
                          state =
