                                    currentTable: table,
                                    currentColumn: table.stockItemId,
                                    referencedTable: $RecipeLineReferences
                                        ._stockItemIdTable(db),
                                    referencedColumn: $RecipeLineReferences
                                        ._stockItemIdTable(db)
                                        .id,
                                  )
                                  as T;
                        }

                        return state;
                      },
                  getPrefetchedDataCallback: (items) async {
                    return [];
                  },
