final class $PrinterReferences
    extends BaseReferences<_$AppDatabase, Printer, PrinterData> {
  $PrinterReferences(super.$_db, super.$_table, super.$_typedResult);

  static MultiTypedResultKey<PrintJob, List<PrintJobData>> _printJobRefsTable(
    _$AppDatabase db,
  ) => MultiTypedResultKey.fromTable(
    db.printJob,
    aliasName: $_aliasNameGenerator(db.printer.id, db.printJob.printerId),
  );

  $PrintJobProcessedTableManager get printJobRefs {
    final manager = $PrintJobTableManager(
      $_db,
      $_db.printJob,
    ).filter((f) => f.printerId.id.sqlEquals($_itemColumn<String>('id')));

    final cache = $_typedResult.readTableOrNull(_printJobRefsTable($_db));
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: cache),
    );
  }
}

